<script setup lang="ts">
import { h,onMounted,ref } from 'vue'
import { NButton,NDataTable,NModal,NInput,NSwitch,NSpace,NInputNumber,NTag,useMessage,type DataTableColumns } from 'naive-ui'
import { listNodes,saveNode,type NodeAdmin } from '../../services/agentWorkflowAdmin'
const rows=ref<NodeAdmin[]>([]);const editing=ref<NodeAdmin|null>(null);const message=useMessage();async function load(){try{rows.value=await listNodes()}catch{message.error('無法載入 Node Catalog')}}async function save(){if(!editing.value)return;try{const x=await saveNode(editing.value);rows.value=rows.value.map(r=>r.nodeType===x.nodeType?x:r);editing.value=null;message.success('已儲存')}catch{message.error('儲存失敗')}}const columns:DataTableColumns<NodeAdmin>=[{title:'Node',key:'displayName'},{title:'Stage',key:'stage'},{title:'Timeout',key:'timeoutSeconds',render:r=>r.timeoutSeconds+'s'},{title:'Retries',key:'maxRetryCount'},{title:'狀態',key:'isEnabled',render:r=>h(NTag,{type:r.isEnabled?'success':'error'},()=>r.isEnabled?'啟用':'停用')},{title:'管理',key:'action',render:r=>h(NButton,{size:'small',onClick:()=>editing.value=structuredClone(r)},()=> '設定')}];onMounted(load)
</script>
<template><main class="tech-page tech-page-fill"><section class="tech-page-header"><div><p class="tech-eyebrow">NODE CATALOG</p><h1>Node 管理</h1></div><NButton class="tech-btn" @click="load">重新整理</NButton></section><section class="tech-panel"><NDataTable :data="rows" :columns="columns" :bordered="false"/></section><NModal :show="!!editing" preset="card" title="Node 設定" @update:show="v=>!v&&(editing=null)"><NSpace v-if="editing" vertical><NInput v-model:value="editing.displayName"/><NInput v-model:value="editing.description" type="textarea"/><NSwitch v-model:value="editing.isEnabled"/><label>Timeout 秒<NInputNumber v-model:value="editing.timeoutSeconds" :min="1" :max="3600"/></label><label>最大重試<NInputNumber v-model:value="editing.maxRetryCount" :min="0" :max="5"/></label><small>Required: {{editing.requiredBlackboardKeys.join(', ')}}</small><small>Produces: {{editing.producedBlackboardKeys.join(', ')}}</small><NButton type="primary" @click="save">儲存</NButton></NSpace></NModal></main></template>
<style scoped>.tech-page{padding:32px}.tech-page-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}label{display:grid;gap:6px}</style>
